type AccordionProps = {
  data: {
    btnText?: string;
    btnLink?: string;
    header: string;
    subTitle: string;
    description: string;
    items: {
      icon: ReactNode;
      image: string;
      title: string;
      content: string;
    }[];
    theme: {
      bg?: string;
      cardBg?: string;
      color?: string;
      subHeader?: string;
      btnClass?: string;
    };
  };
};

const Accordion = ({ data }: AccordionProps) => {
  const [activeIndex, setActiveIndex] = React.useState<number | null>(null);

  const toggleAccordion = (index: number) => {
    setActiveIndex(activeIndex === index ? null : index);
  };

  return (
    <div className="mx-auto w-full space-y-4">
      {data.items.map((item, index: number) => (
        <div key={index} className="rounded-lg shadow-sm">
          {/* Accordion Header */}

          {activeIndex === index ? (
            <></>
          ) : (
            <button
              onClick={() => toggleAccordion(index)}
              className={`flex w-full cursor-pointer items-center justify-between px-6 py-4 text-left text-lg font-medium text-gray-800 focus:outline-none ${data.theme.cardBg}`}
            >
              <div className="flex items-center gap-2">
                {item.icon}
                {item.title}
              </div>

              <div
                onClick={() => toggleAccordion(index)}
                className={`h-[35px] w-[35px] ${data.theme.btnClass} flex cursor-pointer items-center justify-center rounded-full text-lg text-white`}
              >
                <FiPlus />
              </div>
            </button>
          )}

          <div
            className={`overflow-hidden transition-[max-height] duration-300 ease-in-out ${
              activeIndex === index ? "max-h-[250px]" : "max-h-0"
            }`}
          >
            <div className="flex">
              <div className="hidden w-1/2 md:flex">
                <Image
                  src={item.image || ""}
                  width={1000}
                  height={1000}
                  alt=""
                  className="h-full w-full object-cover"
                />
              </div>
              <div
                className={`relative flex min-h-[250px] items-center md:w-1/2 ${data.theme.cardBg}`}
              >
                <div className="px-8">
                  <h4
                    className={`mb-3 flex items-center gap-2 text-xl font-medium ${data.theme.subHeader}`}
                  >
                    {item.icon}
                    {item.title}
                  </h4>
                  <p className="text-[#122C3F]">{item.content}</p>
                </div>
                <div
                  onClick={() => toggleAccordion(index)}
                  className={`absolute top-5 right-5 h-[35px] w-[35px] ${data.theme.btnClass} flex cursor-pointer items-center justify-center rounded-full text-lg text-white`}
                >
                  <FiX />
                </div>
              </div>
            </div>
          </div>
        </div>
      ))}

      {data.btnText && (
        <Button
          className={`${data.theme.btnClass} mx-auto mt-10`}
          text={data.btnText}
          path={data.btnLink}
        />
      )}
    </div>
  );
};
